import { useRef, useState } from 'react';

function Clicks() {
  const clicks = useRef(0);
  const [renders, setRenders] = useState(0);

  function handleClick() {
    clicks.current += 1;
    console.log('clicks:', clicks.current);
  }

  return (
    <>
      <button onClick={handleClick}>Click (ref)</button>
      <button onClick={() => setRenders(renders + 1)}>Re-render</button>
      <p>Clicks shown: {clicks.current}, renders: {renders}</p>
    </>
  );
}

import { useEffect, useRef, useState } from 'react';

function Stopwatch() {
  const [elapsed, setElapsed] = useState(0);
  const intervalRef = useRef(null);

  function start() {
    if (intervalRef.current !== null) return;
    intervalRef.current = setInterval(() => setElapsed((t) => t + 1), 1000);
  }

  function stop() {
    clearInterval(intervalRef.current);
    intervalRef.current = null;
  }

  useEffect(() => () => clearInterval(intervalRef.current), []);

  return (
    <>
      <p>{elapsed} s</p>
      <button onClick={start}>Start</button>
      <button onClick={stop}>Stop</button>
    </>
  );
}

import { useRef } from 'react';

function TextField({ label, ref, ...props }) {
  return (
    <label>
      {label}
      <input ref={ref} {...props} />
    </label>
  );
}

function Form() {
  const emailRef = useRef(null);

  function handleSubmit(e) {
    e.preventDefault();
    if (!emailRef.current.value) emailRef.current.focus();
  }

  return (
    <form onSubmit={handleSubmit}>
      <TextField label="Email" ref={emailRef} type="email" />
      <button>Send</button>
    </form>
  );
}

function Observed() {
  return (
    <div
      ref={(node) => {
        const observer = new ResizeObserver(() => console.log('resized'));
        observer.observe(node);
        return () => observer.disconnect();
      }}
    >
      Resize me
    </div>
  );
}
